<div class="callout info small" style="margin-bottom:18px"><strong>Only you, the Super Admin, can grant or change access.</strong> Everyone else is a normal member (learner, candidate, forum member) unless you give them a scoped role below. Staff roles only see the modules they were given.</div>
<div class="two"><div>
<form class="toolbar" method="get"><input type="search" name="q" value="<?= e($s) ?>" placeholder="Search name or email…"><select name="filter" data-autosubmit><option value="">Everyone</option><option value="staff" <?= $f === 'staff' ? 'selected' : '' ?>>Staff only</option><option value="suspended" <?= $f === 'suspended' ? 'selected' : '' ?>>Suspended</option></select></form>
<div class="table-wrap"><table class="t"><thead><tr><th>User</th><th>Access</th><th>Status</th><th>Last sign-in</th><th></th></tr></thead><tbody><?php foreach ($items as $u): ?><tr><td><div style="display:flex;gap:10px;align-items:center"><?= avatar_html($u, 34) ?><div><strong><?= e($u['name']) ?></strong><div class="muted xs"><?= e($u['email']) ?></div></div></div></td>
<td class="small"><?php if ($u['is_super']): ?><?= badge('Super Admin', 'dark') ?><?php elseif ($u['roles']): foreach (explode(',', $u['roles']) as $r) { echo badge(ucfirst($r), 'blue') . ' '; } else: ?><span class="muted">Member</span><?php endif; ?></td><td><?= badge($u['status'], $u['status'] === 'active' ? 'green' : 'red') ?></td><td class="muted xs"><?= $u['last_login_at'] ? e(ago($u['last_login_at'])) : 'Never' ?></td><td><a class="rowbtn" href="/admin/users/<?= (int) $u['id'] ?>">Manage</a></td></tr><?php endforeach; ?></tbody></table></div><?= pager($pg, '/admin/users', ['q' => $s, 'filter' => $f]) ?></div>
<form class="panel" method="post" action="/admin/users"><?= csrf_field() ?><input type="hidden" name="action" value="create"><div class="panel-h">Add a staff member</div><div class="panel-b form"><?= a_in('Full name', 'name', '', ['required' => true]) ?><?= a_in('Email', 'email', '', ['type' => 'email', 'required' => true]) ?>
<div class="field"><label>Access (choose only what they need)</label><?php foreach (ROLE_LABELS as $k => $v): ?><label class="check" style="margin-bottom:6px"><input type="checkbox" name="roles[]" value="<?= e($k) ?>"><span><?= e($v) ?></span></label><?php endforeach; ?></div>
<button class="btn btn-primary btn-sm">Add and send invitation</button><p class="xs muted mb0">They receive an email to set their own password.</p></div></form></div>
